            if not issubclass(basket_command_middleware, BaseBasketCommandMiddleware):
                continue
            kwargs = dict(
                basket_command_middleware().preprocess_kwargs(
                    basket=self.basket, request=self.request, command=command, kwargs=kwargs
                )
            )
