    pattern = rf"\[(.+)\]\((?!({schemes})).*:(.+)\)"
    value = re.sub(pattern, "[\\1](\\3)", value, flags=re.IGNORECASE)
    html = markdown(value, extensions=["fenced_code", "tables"])
    return mark_safe(html)
