        self.size = size
        self.scale = (1.0, 1.0)
        self.offset = (0.0, 0.0)
        return Rect(
            -self.offset[0],
            -self.offset[1],
            -self.offset[0] + self.size[0] / self.scale[0],
            -self.offset[1] + self.size[1] / self.scale[1],
        )
