        """Deny async functionality."""
        self.not_allowed(node)
    def visit_NamedExpr(self, node):
        """Allow assignment expressions under some circumstances."""
        node = self.node_contents_visit(node)
        target = node.target
        if not isinstance(target, ast.Name):
            self.error(
                node,
                "Assignment expressions are only allowed for simple targets")
        return node

def parse_media_id(request: Request) -> Tuple[str, str, Optional[str]]:
    try:
        postpath: List[bytes] = request.postpath
        assert postpath
        server_name_bytes, media_id_bytes = postpath[:2]
        server_name = server_name_bytes.decode("utf-8")
        media_id = media_id_bytes.decode("utf8")
        file_name = None
        if len(postpath) > 2:
            try:
                file_name = urllib.parse.unquote(postpath[-1].decode("utf-8"))
            except UnicodeDecodeError:
                pass
        return server_name, media_id, file_name
    except Exception:
        raise SynapseError(
            404, "Invalid media id token %r" % (request.postpath,), Codes.UNKNOWN
        )
