    match = ip_regex.findall(_url)
    if len(match):
        ip_address = match[0]
        try:
            ipaddress.ip_address(ip_address)
            return ip_address
        except ValueError:
            pass
    match = domain_regex.findall(_url)
    if len(match):
        return match[0]
    return None
