                    arith = ["seq", ["assert", ["ge", ["add", "l", "r"], "l"]], ["add", "l", "r"]]
                elif isinstance(self.expr.op, vy_ast.Sub):
                    arith = ["seq", ["assert", ["ge", "l", "r"]], ["sub", "l", "r"]]
