    def parse_Decimal(self):
        val = self.expr.value * DECIMAL_DIVISOR
        assert isinstance(val, decimal.Decimal)
        assert SizeLimits.in_bounds("decimal", val)
        assert math.ceil(val) == math.floor(val)
