        else:
            n_bytes = (len(hexstr) - 2) // 2
            val = int(hexstr, 16) << 8 * (32 - n_bytes)
            typ = BaseType(f"bytes{n_bytes}", is_literal=True)
            typ.is_literal = True
            return IRnode.from_list(val, typ=typ)
