            root_dir_path, _ = process_request(
                root=root, path=path, project_uuid=project_uuid
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        app.logger.debug(path)
        if "file" not in request.files or request.files["file"].filename == "":
            return jsonify({"message": "No file found"}), 500
        file = request.files["file"]
        if file and allowed_file(file.filename):
            filename = file.filename.split(os.sep)[-1]
            path = path[1:]
            dir_path = os.path.join(root_dir_path, path)
            if not os.path.isdir(dir_path):
                os.makedirs(dir_path, exist_ok=True)
            file_path = os.path.join(dir_path, filename)
            file.save(file_path)
        return jsonify({"file_path": file_path})
    @app.route("/async/file-management/rename", methods=["POST"])
    def filemanager_rename():
        old_path = request.args.get("old_path")
        new_path = request.args.get("new_path")
        old_root = request.args.get("old_root")
        new_root = request.args.get("new_root")
        project_uuid = request.args.get("project_uuid")
        try:
            old_root_path, _ = process_request(
                root=old_root, path=new_path, project_uuid=project_uuid
            )
            new_root_path, _ = process_request(
                root=new_root, path=new_path, project_uuid=project_uuid
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        abs_old_path = os.path.join(old_root_path, old_path[1:])
        abs_new_path = os.path.join(new_root_path, new_path[1:])
        try:
            os.rename(abs_old_path, abs_new_path)
            return jsonify({"message": "Success"})
        except Exception:
            return jsonify({"message": "Failed to rename"}), 500
    @app.route("/async/file-management/download", methods=["GET"])
    def filemanager_download():
        root = request.args.get("root")
        path = request.args.get("path")
        project_uuid = request.args.get("project_uuid")
        try:
            root_dir_path, _ = process_request(
                root=root, path=path, project_uuid=project_uuid
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        target_path = os.path.join(root_dir_path, path[1:])
        if os.path.isfile(target_path):
            return send_file(target_path, as_attachment=True)
        else:
            memory_file = io.BytesIO()
            with zipfile.ZipFile(memory_file, "w", zipfile.ZIP_STORED) as zf:
                zipdir(target_path, zf)
            memory_file.seek(0)
            return send_file(
                memory_file,
                mimetype="application/zip",
                as_attachment=True,
                attachment_filename=os.path.basename(target_path[:-1]) + ".zip",
            )
    @app.route("/async/file-management/extension-search", methods=["GET"])
    def filemanager_extension_search():
        root = request.args.get("root")
        path = request.args.get("path")
        project_uuid = request.args.get("project_uuid")
        extensions = request.args.get("extensions")
        try:
            root_dir_path, _ = process_request(
                root=root, path=path, project_uuid=project_uuid
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        if extensions is None:
            return jsonify({"message": "extensions is required."}), 400
        path_filter = path
        extensions = extensions.split(",")
        path_filter = path_filter[1:]
        app.logger.info(f"Path filter {path_filter}")
        matches = []
        for extension in extensions:
            matches += list(
                pathlib.Path(os.path.join(root_dir_path, path_filter)).glob(
                    "**/*.{}".format(extension)
                )
            )
        return jsonify(
            {"files": [os.path.relpath(str(match), root_dir_path) for match in matches]}
        )
    @app.route("/async/file-management/browse", methods=["GET"])
    def browse_files():
        root = request.args.get("root")
        path = request.args.get("path")
        depth_as_string = request.args.get("depth")
        project_uuid = request.args.get("project_uuid")
        try:
            root_dir_path, depth = process_request(
                root=root,
                path=path,
                project_uuid=project_uuid,
                depth=depth_as_string,
                is_path_required=False,
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        path_filter = path if path else "/"
        app.logger.info(f"Path filter {path_filter}")
        return jsonify(
            generate_tree(root_dir_path, path_filter=path_filter, depth=depth)
        )

def create_app(to_migrate_db=False):
    """Create the Flask app and return it.
    Args:
        to_migrate_db: If True, then only initialize the db.
    Returns:
        Flask.app
    """
    signal.signal(signal.SIGTERM, lambda *args, **kwargs: sys.exit(0))
    app = Flask(__name__)
    app.config.from_object(config.CONFIG_CLASS)
    init_logging()
    if os.getenv("FLASK_ENV") == "development":
        app = register_teardown_request(app)
    socketio = SocketIO(app, cors_allowed_origins="*")
    try:
        global_orchest_config = _utils.GlobalOrchestConfig()
    except _errors.CorruptedFileError:
        app.logger.error("Failed to load global orchest config file.", exc_info=True)
    else:
        app.config.update(global_orchest_config.as_dict())
        global_orchest_config.save(app)
    app.config["ORCHEST_REPO_TAG"] = get_repo_tag()
    if not database_exists(app.config["SQLALCHEMY_DATABASE_URI"]):
        create_database(app.config["SQLALCHEMY_DATABASE_URI"])
    db.init_app(app)
    ma.init_app(app)
    Migrate().init_app(app, db)
    if to_migrate_db:
        return app, None, None
    app.logger.info("Flask CONFIG: %s" % app.config)
    if not app.config["TELEMETRY_DISABLED"]:
        posthog.api_key = base64.b64decode(app.config["POSTHOG_API_KEY"]).decode()
        posthog.host = app.config["POSTHOG_HOST"]
    if not _utils.is_running_from_reloader():
        with app.app_context():
            try:
                if app.config.get("TESTING", False):
                    pass
                else:
                    app.logger.debug("Trying to create /tmp/webserver_init_lock")
                    os.mkdir("/tmp/webserver_init_lock")
                    app.logger.info("/tmp/webserver_init_lock successfully created.")
            except FileExistsError:
                app.logger.info("/tmp/webserver_init_lock already exists.")
            else:
                jupyter_boot_lock_path = os.path.join(
                    "/userdir", _config.JUPYTER_USER_CONFIG, "lab", ".bootlock"
                )
                if os.path.exists(jupyter_boot_lock_path):
                    app.logger.info("Removing dangling jupyter boot lock.")
                    os.rmdir(jupyter_boot_lock_path)
                projs = Project.query.all()
                for proj in projs:
                    try:
                        populate_kernels(app, db, proj.uuid)
                    except Exception as e:
                        logging.error(
                            "Failed to populate kernels on startup"
                            " for project %s: %s [%s]" % (proj.uuid, e, type(e))
                        )
    scheduler = BackgroundScheduler(
        job_defaults={
            "misfire_grace_time": 2 ** 31,
            "coalesce": False,
            "max_instances": 2 ** 31,
        }
    )
    app.config["SCHEDULER"] = scheduler
    add_recurring_jobs_to_scheduler(scheduler, app, run_on_add=True)
    scheduler.start()
    @app.route("/", defaults={"path": ""}, methods=["GET"])
    @app.route("/<path:path>", methods=["GET"])
    def index(path):
        file_path = safe_join(app.config["STATIC_DIR"], path)
        if os.path.isfile(file_path):
            return send_from_directory(app.config["STATIC_DIR"], path)
        else:
            return send_from_directory(
                app.config["STATIC_DIR"], "index.html", cache_timeout=0
            )
    register_views(app, db)
    register_orchest_api_views(app, db)
    register_background_tasks_view(app, db)
    register_socketio_broadcast(socketio)
    register_analytics_views(app, db)
    processes = []
    if (
        os.environ.get("FLASK_ENV") != "development"
        or _utils.is_running_from_reloader()
    ):
        file_dir = os.path.dirname(os.path.realpath(__file__))
        log_streamer_process = Popen(
            ["python3", "-m", "scripts.log_streamer"],
            cwd=os.path.join(file_dir, ".."),
            stderr=subprocess.STDOUT,
        )
        app.logger.info("Started log_streamer.py")
        processes.append(log_streamer_process)
    return app, socketio, processes
