            if not os.path.isfile(pipeline_json_path):
                return (
                    jsonify(
                        {
                            "success": False,
                            "reason": ".orchest file doesn't exist at location "
                            + pipeline_json_path,
                        }
                    ),
                    404,
                )
            else:
                pipeline_json = get_pipeline_json(pipeline_uuid, project_uuid)
                return jsonify(
                    {"success": True, "pipeline_json": json.dumps(pipeline_json)}
                )
