            return b''
        encoding = self.repo._encoding.name
        if self._is_compressed:
            zcat = subprocess.Popen([b'zcat', self.path], stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
            return subprocess.check_output(
                ['tail', '-n', str(num)],
                stdin=zcat.stdout,
                stderr=subprocess.STDOUT,
                encoding=encoding,
                errors='replace',
            )
