            sys.stdout.write(o[:lastNewLine+1])
        else:
            lastLine = o.strip()
        if e:
            sys.stderr.write(e)
        try:
            json_output = json.loads(lastLine)
            if isinstance(json_output, dict):
                return (200, json_output)
            else:
                return error(lastLine)
        except Exception:
            return error(lastLine)
