    return id, title
class Pdata(Persistent, Implicit):
    next = None
    def __init__(self, data):
        self.data = data
    def __getitem__(self, key):
        return self.data[key]
    def __len__(self):
        data = bytes(self)
        return len(data)
    def __bytes__(self):
        _next = self.next
        if _next is None:
            return self.data
        r = [self.data]
        while _next is not None:
            self = _next
            r.append(self.data)
            _next = self.next
        return b''.join(r)

