def user_agent():
    """
    Return a string representing the user agent.
    """
    data = {
        "installer": {"name": "pip", "version": pip.__version__},
        "python": platform.python_version(),
        "implementation": {
            "name": platform.python_implementation(),
        },
    }
    if data["implementation"]["name"] == 'CPython':
        data["implementation"]["version"] = platform.python_version()
    elif data["implementation"]["name"] == 'PyPy':
        if sys.pypy_version_info.releaselevel == 'final':
            pypy_version_info = sys.pypy_version_info[:3]
        else:
            pypy_version_info = sys.pypy_version_info
        data["implementation"]["version"] = ".".join(
            [str(x) for x in pypy_version_info]
        )
    elif data["implementation"]["name"] == 'Jython':
        data["implementation"]["version"] = platform.python_version()
    elif data["implementation"]["name"] == 'IronPython':
        data["implementation"]["version"] = platform.python_version()
    if sys.platform.startswith("linux"):
        from pip._vendor import distro
        distro_infos = dict(filter(
            lambda x: x[1],
            zip(["name", "version", "id"], distro.linux_distribution()),
        ))
        libc = dict(filter(
            lambda x: x[1],
            zip(["lib", "version"], libc_ver()),
        ))
        if libc:
            distro_infos["libc"] = libc
        if distro_infos:
            data["distro"] = distro_infos
    if sys.platform.startswith("darwin") and platform.mac_ver()[0]:
        data["distro"] = {"name": "macOS", "version": platform.mac_ver()[0]}
    if platform.system():
        data.setdefault("system", {})["name"] = platform.system()
    if platform.release():
        data.setdefault("system", {})["release"] = platform.release()
    if platform.machine():
        data["cpu"] = platform.machine()
    if HAS_TLS:
        data["openssl_version"] = ssl.OPENSSL_VERSION
    setuptools_version = get_installed_version("setuptools")
    if setuptools_version is not None:
        data["setuptools_version"] = setuptools_version
    data["ci"] = True if looks_like_ci() else None
    user_data = os.environ.get("PIP_USER_AGENT_USER_DATA")
    if user_data is not None:
        data["user_data"] = user_data
    return "{data[installer][name]}/{data[installer][version]} {json}".format(
        data=data,
        json=json.dumps(data, separators=(",", ":"), sort_keys=True),
    )
def _get_keyring_auth(url, username):
    """Return the tuple auth for a given url from keyring."""
    if not url or not keyring:
        return None
    try:
        try:
            get_credential = keyring.get_credential
        except AttributeError:
            pass
        else:
            logger.debug("Getting credentials from keyring for %s", url)
            cred = get_credential(url, username)
            if cred is not None:
                return cred.username, cred.password
            return None
        if username:
            logger.debug("Getting password from keyring for %s", url)
            password = keyring.get_password(url, username)
            if password:
                return username, password
    except Exception as exc:
        logger.warning("Keyring is skipped due to an exception: %s",
                       str(exc))
class MultiDomainBasicAuth(AuthBase):
    def __init__(self, prompting=True, index_urls=None):
        self.prompting = prompting
        self.index_urls = index_urls
        self.passwords = {}
        self._credentials_to_save = None
    def _get_index_url(self, url):
        """Return the original index URL matching the requested URL.
        Cached or dynamically generated credentials may work against
        the original index URL rather than just the netloc.
        The provided url should have had its username and password
        removed already. If the original index url had credentials then
        they will be included in the return value.
        Returns None if no matching index was found, or if --no-index
        was specified by the user.
        """
        if not url or not self.index_urls:
            return None
        for u in self.index_urls:
            prefix = remove_auth_from_url(u).rstrip("/") + "/"
            if url.startswith(prefix):
                return u
    def _get_new_credentials(self, original_url, allow_netrc=True,
                             allow_keyring=True):
        """Find and return credentials for the specified URL."""
        url, netloc, url_user_password = split_auth_netloc_from_url(
            original_url)
        username, password = url_user_password
        if username is not None and password is not None:
            logger.debug("Found credentials in url for %s", netloc)
            return url_user_password
        index_url = self._get_index_url(url)
        if index_url:
            index_info = split_auth_netloc_from_url(index_url)
            if index_info:
                index_url, _, index_url_user_password = index_info
                logger.debug("Found index url %s", index_url)
        if index_url and index_url_user_password[0] is not None:
            username, password = index_url_user_password
            if username is not None and password is not None:
                logger.debug("Found credentials in index url for %s", netloc)
                return index_url_user_password
        if allow_netrc:
            netrc_auth = get_netrc_auth(original_url)
            if netrc_auth:
                logger.debug("Found credentials in netrc for %s", netloc)
                return netrc_auth
        if allow_keyring:
            kr_auth = (_get_keyring_auth(index_url, username) or
                       _get_keyring_auth(netloc, username))
            if kr_auth:
                logger.debug("Found credentials in keyring for %s", netloc)
                return kr_auth
        return None, None
    def _get_url_and_credentials(self, original_url):
        """Return the credentials to use for the provided URL.
        If allowed, netrc and keyring may be used to obtain the
        correct credentials.
        Returns (url_without_credentials, username, password). Note
        that even if the original URL contains credentials, this
        function may return a different username and password.
        """
        url, netloc, _ = split_auth_netloc_from_url(original_url)
        username, password = self.passwords.get(netloc, (None, None))
        if username is None or password is None:
            username, password = self._get_new_credentials(original_url)
        if username is not None and password is not None:
            self.passwords[netloc] = (username, password)
        return url, username, password
    def __call__(self, req):
        url, username, password = self._get_url_and_credentials(req.url)
        req.url = url
        if username is not None and password is not None:
            req = HTTPBasicAuth(username, password)(req)
        req.register_hook("response", self.handle_401)
        return req
    def _prompt_for_password(self, netloc):
        username = ask_input("User for %s: " % netloc)
        if not username:
            return None, None
        auth = _get_keyring_auth(netloc, username)
        if auth:
            return auth[0], auth[1], False
        password = ask_password("Password: ")
        return username, password, True
    def _should_save_password_to_keyring(self):
        if not keyring:
            return False
        return ask("Save credentials to keyring [y/N]: ", ["y", "n"]) == "y"
    def handle_401(self, resp, **kwargs):
        if resp.status_code != 401:
            return resp
        if not self.prompting:
            return resp
        parsed = urllib_parse.urlparse(resp.url)
        username, password, save = self._prompt_for_password(parsed.netloc)
        self._credentials_to_save = None
        if username is not None and password is not None:
            self.passwords[parsed.netloc] = (username, password)
            if save and self._should_save_password_to_keyring():
                self._credentials_to_save = (parsed.netloc, username, password)
        resp.content
        resp.raw.release_conn()
        req = HTTPBasicAuth(username or "", password or "")(resp.request)
        req.register_hook("response", self.warn_on_401)
        if self._credentials_to_save:
            req.register_hook("response", self.save_credentials)
        new_resp = resp.connection.send(req, **kwargs)
        new_resp.history.append(resp)
        return new_resp
    def warn_on_401(self, resp, **kwargs):
        """Response callback to warn about incorrect credentials."""
        if resp.status_code == 401:
            logger.warning('401 Error, Credentials not correct for %s',
                           resp.request.url)
    def save_credentials(self, resp, **kwargs):
        """Response callback to save credentials on success."""
        assert keyring is not None, "should never reach here without keyring"
        if not keyring:
            return
        creds = self._credentials_to_save
        self._credentials_to_save = None
        if creds and resp.status_code < 400:
            try:
                logger.info('Saving credentials to keyring')
                keyring.set_password(*creds)
            except Exception:
                logger.exception('Failed to save credentials')
class LocalFSAdapter(BaseAdapter):
    def send(self, request, stream=None, timeout=None, verify=None, cert=None,
             proxies=None):
        pathname = url_to_path(request.url)
        resp = Response()
        resp.status_code = 200
        resp.url = request.url
        try:
            stats = os.stat(pathname)
        except OSError as exc:
            resp.status_code = 404
            resp.raw = exc
        else:
            modified = email.utils.formatdate(stats.st_mtime, usegmt=True)
            content_type = mimetypes.guess_type(pathname)[0] or "text/plain"
            resp.headers = CaseInsensitiveDict({
                "Content-Type": content_type,
                "Content-Length": stats.st_size,
                "Last-Modified": modified,
            })
            resp.raw = open(pathname, "rb")
            resp.close = resp.raw.close
        return resp
class SafeFileCache(FileCache):
